function processOrder(amount, discountCallback, feeCallback) {
  const discounted = discountCallback(amount);
  return feeCallback(discounted);
}
function getFinalOrderAmount(amount) {
  const discount = (value) => value * 0.9;
  const addFee = (value) => value + 3000;
  return processOrder(amount, discount, addFee);
}
